  'consent.mobileFirst': { en: 'Mobile-First', he: 'Mobile-First', ar: 'Mobile-First', ru: 'Mobile-First', fr: 'Mobile-First', es: 'Mobile-First' },
  'consent.googleDesc': { en: 'Professional consent screen requesting full access to Gmail, Contacts, and Google Calendar. Perfect for enterprise applications and CRM.', he: 'מסך הסכמה מקצועי המבקש גישה מלאה ל-Gmail, אנשי קשר ויומן Google. מתאים לאפליקציות ארגוניות ו-CRM.', ar: 'شاشة موافقة احترافية تطلب وصول كامل إلى Gmail وجهات الاتصال وتقويم Google. مثالية لتطبيقات المؤسسات وإدارة علاقات العملاء.', ru: 'Профессиональный экран согласия с запросом полного доступа к Gmail, контактам и календарю Google. Идеально для корпоративных приложений и CRM.', fr: 'Écran de consentement professionnel demandant un accès complet à Gmail, Contacts et Google Calendar. Parfait pour les applications d\'entreprise et CRM.', es: 'Pantalla de consentimiento profesional solicitando acceso completo a Gmail, Contactos y Google Calendar. Perfecta para aplicaciones empresariales y CRM.' },
  'consent.iosDesc': { en: 'Professional iOS-style permissions guide. Shows all required app permissions with clear explanations.', he: 'מדריך הרשאות iOS מקצועי בסגנון ההגדרות של אפל. מציג את כל ההרשאות הנדרשות לאפליקציה עם הסברים ברורים.', ar: 'دليل أذونات بأسلوب iOS الاحترافي. يعرض جميع أذونات التطبيق المطلوبة مع شروحات واضحة.', ru: 'Профессиональное руководство по разрешениям в стиле iOS. Показывает все необходимые разрешения приложения с понятными объяснениями.', fr: 'Guide de permissions professionnel de style iOS. Affiche toutes les autorisations d\'application requises avec des explications claires.', es: 'Guía de permisos profesional estilo iOS. Muestra todos los permisos de aplicación requeridos con explicaciones claras.' },
  'consent.designDesc': { en: 'Pixel-perfect match to official Google and Apple consent screens', he: 'עיצוב זהה למסכי ההסכמה הרשמיים של Google ו-Apple', ar: 'تطابق دقيق مع شاشات موافقة Google وApple الرسمية', ru: 'Точное соответствие официальным экранам согласия Google и Apple', fr: 'Correspondance parfaite avec les écrans de consentement officiels de Google et Apple', es: 'Coincidencia perfecta con las pantallas de consentimiento oficiales de Google y Apple' },
  'consent.gdprDesc': { en: '7-year audit retention for all consent records', he: 'תיעוד מלא של כל ההסכמות עם שמירה למשך 7 שנים', ar: 'الاحتفاظ بسجلات التدقيق لمدة 7 سنوات لجميع سجلات الموافقة', ru: 'Хранение записей согласия для аудита в течение 7 лет', fr: 'Conservation d\'audit de 7 ans pour tous les enregistrements de consentement', es: 'Retención de auditoría de 7 años para todos los registros de consentimiento' },
  'consent.multilingualDesc': { en: 'Full Hebrew, English, and RTL/LTR support', he: 'תמיכה מלאה בעברית, אנגלית וכיוון RTL/LTR', ar: 'دعم كامل للعبرية والإنجليزية وRTL/LTR', ru: 'Полная поддержка иврита, английского и RTL/LTR', fr: 'Support complet de l\'hébreu, de l\'anglais et RTL/LTR', es: 'Soporte completo de hebreo, inglés y RTL/LTR' },
  'consent.mobileDesc': { en: 'Fully optimized for mobile with smooth animations', he: 'אופטימיזציה מלאה למובייל עם אנימציות חלקות', ar: 'محسّن بالكامل للجوال مع رسوم متحركة سلسة', ru: 'Полностью оптимизировано для мобильных устройств с плавной анимацией', fr: 'Entièrement optimisé pour mobile avec des animations fluides', es: 'Completamente optimizado para móvil con animaciones suaves' },
  'consent.demoAlert': { en: 'This is demo mode only. In production, this would trigger the Google sign-in flow.', he: 'זהו מצב הדגמה בלבד. בייצור, זה יפעיל את תהליך ההתחברות של Google.', ar: 'هذا وضع تجريبي فقط. في الإنتاج، سيؤدي هذا إلى تشغيل عملية تسجيل الدخول إلى Google.', ru: 'Это только демонстрационный режим. В производстве это запустит процесс входа в Google.', fr: 'Ceci est en mode démo uniquement. En production, cela déclencherait le flux de connexion Google.', es: 'Esto es solo modo demostración. En producción, esto activaría el flujo de inicio de sesión de Google.' },
  // Gmail Demo
  'gmailDemo.title': { en: 'Premium Gmail Sign-in', he: 'התחברות Gmail Premium', ar: 'تسجيل دخول Gmail المتميز', ru: 'Премиум вход в Gmail', fr: 'Connexion Gmail Premium', es: 'Inicio de sesión Gmail Premium' },
  'gmailDemo.heroDescription': { en: 'Experience the beautiful Google permission screen - just like big tech companies do!', he: 'התנסה במסך ההרשאות המהמם של Google - כמו שחברות הטכנולוגיה הגדולות עושות!', ar: 'جرب شاشة أذونات Google الجميلة - تماماً كما تفعل شركات التكنولوجيا الكبرى!', ru: 'Испытайте красивый экран разрешений Google - как большие технологические компании!', fr: 'Découvrez le magnifique écran d\'autorisation Google - comme les grandes entreprises tech!', es: 'Experimenta la hermosa pantalla de permisos de Google - ¡como lo hacen las grandes empresas tecnológicas!' },
  'gmailDemo.whatHappens': { en: 'What happens when you click', he: 'מה יקרה כשתלחץ', ar: 'ماذا يحدث عندما تنقر', ru: 'Что происходит при нажатии', fr: 'Ce qui se passe quand vous cliquez', es: 'Qué sucede cuando haces clic' },
  'gmailDemo.googlePopup': { en: '📱 Google popup opens', he: '📱 נפתח חלון קופץ של Google', ar: '📱 يفتح نافذة Google المنبثقة', ru: '📱 Открывается всплывающее окно Google', fr: '📱 Popup Google s\'ouvre', es: '📱 Se abre ventana emergente de Google' },
  'gmailDemo.step1Description': { en: 'Beautiful Google sign-in screen appears on your iPhone', he: 'מסך התחברות מהמם של Google יופיע על האייפון שלך', ar: 'تظهر شاشة تسجيل دخول Google الجميلة على iPhone الخاص بك', ru: 'Красивый экран входа Google появляется на вашем iPhone', fr: 'Un magnifique écran de connexion Google apparaît sur votre iPhone', es: 'Hermosa pantalla de inicio de sesión de Google aparece en tu iPhone' },
  'gmailDemo.permissionScreen': { en: '🔐 Amazing permission screen', he: '🔐 מסך ההרשאות המדהים', ar: '🔐 شاشة الأذونات المذهلة', ru: '🔐 Удивительный экран разрешений', fr: '🔐 Écran d\'autorisation incroyable', es: '🔐 Pantalla de permisos increíble' },
  'gmailDemo.step2Description': { en: 'Google asks: "Pet Wash™️ wants to access your Gmail"', he: 'Google ישאל: "Pet Wash™️ רוצה לגשת ל-Gmail שלך"', ar: 'يسأل Google: "Pet Wash™️ يريد الوصول إلى Gmail الخاص بك"', ru: 'Google спрашивает: "Pet Wash™️ хочет получить доступ к вашей почте Gmail"', fr: 'Google demande: "Pet Wash™️ veut accéder à votre Gmail"', es: 'Google pregunta: "Pet Wash™️ quiere acceder a tu Gmail"' },
