  'standaloneDivisions.crossSellingDesc': { en: 'Customers from one division can discover others', he: 'לקוחות מאחת החטיבות יכולים לגלות אחרות', ar: 'يمكن للعملاء من قسم واحد اكتشاف أقسام أخرى', ru: 'Клиенты одного подразделения могут открыть для себя другие', fr: 'Les clients d\'une division peuvent en découvrir d\'autres', es: 'Los clientes de una división pueden descubrir otras' },
  'standaloneDivisions.freeDivisionDesc': { en: 'The Plush Lab™ is available to everyone for free - No sign-up required', he: 'The Plush Lab™ זמין לכולם בחינם - ללא צורך בהרשמה', ar: 'The Plush Lab™ متاح للجميع مجانًا - لا حاجة للتسجيل', ru: 'The Plush Lab™ доступен всем бесплатно - регистрация не требуется', fr: 'The Plush Lab™ est disponible gratuitement pour tous - Aucune inscription requise', es: 'The Plush Lab™ está disponible para todos gratis - No se requiere registro' },
