  'settings.addPasskeyQuick': { en: 'Add a passkey to this device to sign in quickly and securely', he: 'הוסף Passkey למכשיר זה כדי להתחבר במהירות ובאופן מאובטח', ar: 'أضف مفتاح مرور إلى هذا الجهاز لتسجيل الدخول بسرعة وأمان', ru: 'Добавьте ключ доступа на это устройство для быстрого и безопасного входа', fr: 'Ajoutez une clé d\'accès à cet appareil pour vous connecter rapidement et en toute sécurité', es: 'Agrega una clave de acceso a este dispositivo para iniciar sesión de forma rápida y segura' },
  'settings.browserNoPasskey': { en: 'Your browser doesn\'t support passkeys. Try Chrome, Safari, or Edge.', he: 'הדפדפן שלך אינו תומך ב-Passkeys. נסה Chrome, Safari, או Edge עדכני.', ar: 'متصفحك لا يدعم مفاتيح المرور. جرب Chrome أو Safari أو Edge.', ru: 'Ваш браузер не поддерживает ключи доступа. Попробуйте Chrome, Safari или Edge.', fr: 'Votre navigateur ne prend pas en charge les clés d\'accès. Essayez Chrome, Safari ou Edge.', es: 'Tu navegador no admite claves de acceso. Prueba Chrome, Safari o Edge.' },
  'settings.removeDeviceDesc': { en: 'You won\'t be able to use the passkey from this device anymore. This action cannot be undone.', he: 'לא תוכל להשתמש ב-Passkey מהמכשיר הזה יותר. פעולה זו אינה ניתנת לביטול.', ar: 'لن تتمكن من استخدام مفتاح المرور من هذا الجهاز بعد الآن. لا يمكن التراجع عن هذا الإجراء.', ru: 'Вы больше не сможете использовать ключ доступа с этого устройства. Это действие нельзя отменить.', fr: 'Vous ne pourrez plus utiliser la clé d\'accès de cet appareil. Cette action ne peut pas être annulée.', es: 'Ya no podrás usar la clave de acceso desde este dispositivo. Esta acción no se puede deshacer.' },
  'settings.deleteAccountWarning': { en: 'This action will permanently delete your account and cannot be recovered!', he: 'פעולה זו תמחק לצמיתות את החשבון שלך ואינה ניתנת לשחזור!', ar: 'سيؤدي هذا الإجراء إلى حذف حسابك نهائيًا ولا يمكن استرداده!', ru: 'Это действие навсегда удалит ваш аккаунт и не может быть восстановлено!', fr: 'Cette action supprimera définitivement votre compte et ne peut pas être récupérée!', es: '¡Esta acción eliminará permanentemente tu cuenta y no se puede recuperar!' },
  'settings.followingDeleted': { en: 'The following data will be permanently deleted:', he: 'כל הנתונים הבאים יימחקו לצמיתות:', ar: 'سيتم حذف البيانات التالية نهائيًا:', ru: 'Следующие данные будут удалены навсегда:', fr: 'Les données suivantes seront définitivement supprimées:', es: 'Los siguientes datos se eliminarán permanentemente:' },
  'settings.confirmEmailContinue': { en: 'Confirm your email address to continue:', he: 'אשר את כתובת האימייל שלך כדי להמשיך:', ar: 'قم بتأكيد عنوان بريدك الإلكتروني للمتابعة:', ru: 'Подтвердите свой email для продолжения:', fr: 'Confirmez votre adresse email pour continuer:', es: 'Confirma tu dirección de correo electrónico para continuar:' },
  'settings.typeEmail': { en: 'Type:', he: 'הקלד:', ar: 'اكتب:', ru: 'Введите:', fr: 'Tapez:', es: 'Escribe:' },
  'settings.finalWarning': { en: 'After clicking "Delete Permanently", your account will be deleted forever with NO RECOVERY.', he: 'לאחר לחיצה על "מחק לצמיתות", החשבון שלך יימחק לצמיתות ללא אפשרות שחזור.', ar: 'بعد النقر على "حذف نهائيًا"، سيتم حذف حسابك إلى الأبد بدون استرداد.', ru: 'После нажатия "Удалить навсегда" ваш аккаунт будет удален навсегда БЕЗ ВОССТАНОВЛЕНИЯ.', fr: 'Après avoir cliqué sur "Supprimer définitivement", votre compte sera supprimé définitivement SANS RÉCUPÉRATION.', es: 'Después de hacer clic en "Eliminar permanentemente", tu cuenta se eliminará para siempre SIN RECUPERACIÓN.' },
  'settings.typeTextExactly': { en: 'Type the following text exactly to confirm:', he: 'הקלד את הטקסט הבא בדיוק כדי לאשר:', ar: 'اكتب النص التالي بالضبط للتأكيد:', ru: 'Введите следующий текст точно для подтверждения:', fr: 'Tapez exactement le texte suivant pour confirmer:', es: 'Escribe exactamente el siguiente texto para confirmar:' },
