  'kyc.req4': { en: 'Min size: 50KB, Max size: 10MB', he: 'גודל מינימלי: 50KB, מקסימלי: 10MB', ar: 'الحجم الأدنى: 50KB، الأقصى: 10MB', ru: 'Мин. размер: 50КБ, Макс. размер: 10МБ', fr: 'Taille min: 50KB, Taille max: 10MB', es: 'Tamaño mín: 50KB, Tamaño máx: 10MB' },
  'kyc.req5': { en: 'Your information is encrypted and secure', he: 'המידע שלך מוצפן ומאובטח', ar: 'معلوماتك مشفرة وآمنة', ru: 'Ваша информация зашифрована и защищена', fr: 'Vos informations sont cryptées et sécurisées', es: 'Tu información está encriptada y segura' },
  'kyc.guidelines': { en: 'Upload Guidelines', he: 'הנחיות העלאה', ar: 'إرشادات التحميل', ru: 'Рекомендации по загрузке', fr: 'Directives de téléchargement', es: 'Directrices de carga' },
  'kyc.guidelineText': { en: 'We respect your privacy. Documents are encrypted and securely stored. Only authorized staff can view documents for verification purposes.', he: 'אנו מכבדים את פרטיותך. המסמך מוצפן ומאוחסן בצורה מאובטחת. רק צוות מורשה יוכל לראות את המסמך לצורך אימות.', ar: 'نحن نحترم خصوصيتك. المستندات مشفرة ومخزنة بشكل آمن. يمكن فقط للموظفين المصرح لهم عرض المستندات لأغراض التحقق.', ru: 'Мы уважаем вашу конфиденциальность. Документы зашифрованы и надежно хранятся. Только уполномоченный персонал может просматривать документы для проверки.', fr: 'Nous respectons votre vie privée. Les documents sont cryptés et stockés en toute sécurité. Seul le personnel autorisé peut consulter les documents à des fins de vérification.', es: 'Respetamos tu privacidad. Los documentos están encriptados y almacenados de forma segura. Solo el personal autorizado puede ver los documentos para fines de verificación.' },
  'kyc.privacyNote': { en: 'Documents are retained for 12 months and then automatically deleted', he: 'המסמכים נשמרים למשך 12 חודשים ולאחר מכן נמחקים אוטומטית', ar: 'يتم الاحتفاظ بالمستندات لمدة 12 شهرًا ثم يتم حذفها تلقائيًا', ru: 'Документы хранятся 12 месяцев, затем автоматически удаляются', fr: 'Les documents sont conservés pendant 12 mois puis supprimés automatiquement', es: 'Los documentos se conservan durante 12 meses y luego se eliminan automáticamente' },
  'kyc.success': { en: 'Success!', he: 'הצלחה!', ar: 'نجاح!', ru: 'Успех!', fr: 'Succès!', es: '¡Éxito!' },
  'kyc.successMsg': { en: 'Document uploaded successfully. We will review it within 24 hours.', he: 'המסמך הועלה בהצלחה. נבדוק אותו תוך 24 שעות.', ar: 'تم تحميل المستند بنجاح. سنراجعه خلال 24 ساعة.', ru: 'Документ успешно загружен. Мы проверим его в течение 24 часов.', fr: 'Document téléchargé avec succès. Nous l\'examinerons dans les 24 heures.', es: 'Documento subido exitosamente. Lo revisaremos dentro de 24 horas.' },
  'kyc.error': { en: 'Error', he: 'שגיאה', ar: 'خطأ', ru: 'Ошибка', fr: 'Erreur', es: 'Error' },
