  'kyc.reviewing': { en: 'Your document is under review. Average response time: 24 hours', he: 'המסמך שלך בבדיקה. זמן תגובה ממוצע: 24 שעות', ar: 'مستندك قيد المراجعة. متوسط وقت الاستجابة: 24 ساعة', ru: 'Ваш документ на рассмотрении. Среднее время ответа: 24 часа', fr: 'Votre document est en cours d\'examen. Temps de réponse moyen: 24 heures', es: 'Tu documento está en revisión. Tiempo de respuesta promedio: 24 horas' },
  'kyc.approvedMsg': { en: 'Your discount has been approved! It will apply automatically at checkout.', he: 'ההנחה שלך אושרה! היא תחול אוטומטית בקופה.', ar: 'تمت الموافقة على خصمك! سيتم تطبيقه تلقائيًا عند الدفع.', ru: 'Ваша скидка одобрена! Она будет применена автоматически при оплате.', fr: 'Votre réduction a été approuvée! Elle s\'appliquera automatiquement lors du paiement.', es: '¡Tu descuento ha sido aprobado! Se aplicará automáticamente al pagar.' },
  'kyc.rejectedMsg': { en: 'Document was rejected. Please upload a new document.', he: 'המסמך נדחה. אנא העלה מסמך חדש.', ar: 'تم رفض المستند. يرجى تحميل مستند جديد.', ru: 'Документ отклонен. Пожалуйста, загрузите новый документ.', fr: 'Le document a été rejeté. Veuillez télécharger un nouveau document.', es: 'El documento fue rechazado. Por favor sube un nuevo documento.' },
