  'kyc.fileTooLarge': { en: 'File too large (max 10MB)', he: 'הקובץ גדול מדי (מקסימום 10MB)', ar: 'الملف كبير جدًا (الحد الأقصى 10 ميجابايت)', ru: 'Файл слишком большой (макс. 10МБ)', fr: 'Fichier trop volumineux (max 10MB)', es: 'Archivo demasiado grande (máx 10MB)' },
  'kyc.fileTooSmall': { en: 'File too small (min 50KB)', he: 'הקובץ קטן מדי (מינימום 50KB)', ar: 'الملف صغير جدًا (الحد الأدنى 50 كيلوبايت)', ru: 'Файл слишком маленький (мин. 50КБ)', fr: 'Fichier trop petit (min 50KB)', es: 'Archivo demasiado pequeño (mín 50KB)' },
  'kyc.uploadFailed': { en: 'Upload failed', he: 'העלאה נכשלה', ar: 'فشل التحميل', ru: 'Загрузка не удалась', fr: 'Échec du téléchargement', es: 'Fallo en la carga' },
