  // Franchise Page Additional
  'franchise.aiAdvisorDesc': { en: 'Get instant answers to any franchise question about ROI, locations, and support - powered by advanced AI', he: 'קבל תשובות מיידיות לכל שאלה על הזכיינות, ROI, מיקומים ותמיכה - מופעל על ידי AI מתקדם', ar: 'احصل على إجابات فورية لأي سؤال حول الامتياز حول عائد الاستثمار والمواقع والدعم - مدعوم بالذكاء الاصطناعي المتقدم', ru: 'Получите мгновенные ответы на любые вопросы о франшизе, ROI, локациях и поддержке - на базе передового ИИ', fr: 'Obtenez des réponses instantanées à toute question sur la franchise concernant le ROI, les emplacements et le support - alimenté par une IA avancée', es: 'Obtén respuestas instantáneas a cualquier pregunta sobre franquicia acerca de ROI, ubicaciones y soporte - impulsado por IA avanzada' },
  'franchise.vrTourDesc': { en: 'Experience the K9000 station in 3D before you invest - tour equipment, layout, and operations in real-time', he: 'חווה את עמדת K9000 בתלת ממד לפני שאתה משקיע - סייר בציוד, פריסה ותפעול בזמן אמת', ar: 'اختبر محطة K9000 بتقنية ثلاثية الأبعاد قبل الاستثمار - جولة في المعدات والتخطيط والعمليات في الوقت الفعلي', ru: 'Испытайте станцию K9000 в 3D перед инвестированием - осмотрите оборудование, планировку и операции в реальном времени', fr: 'Découvrez la station K9000 en 3D avant d\'investir - visitez l\'équipement, l\'aménagement et les opérations en temps réel', es: 'Experimenta la estación K9000 en 3D antes de invertir - recorre equipos, diseño y operaciones en tiempo real' },
  'franchise.aiPrediction': { en: 'Based on analysis of 500+ franchisees, our AI predicts a 92% success probability for this location', he: 'בהתבסס על ניתוח 500+ זכיינים, ה-AI שלנו חוזה סבירות הצלחה של 92% למיקום זה', ar: 'استنادًا إلى تحليل أكثر من 500 صاحب امتياز، يتوقع الذكاء الاصطناعي لدينا احتمالية نجاح بنسبة 92٪ لهذا الموقع', ru: 'На основе анализа 500+ франчайзи, наш ИИ предсказывает 92% вероятность успеха для этой локации', fr: 'Sur la base de l\'analyse de plus de 500 franchisés, notre IA prédit une probabilité de succès de 92% pour cet emplacement', es: 'Basándonos en el análisis de más de 500 franquiciados, nuestra IA predice una probabilidad de éxito del 92% para esta ubicación' },
  'franchise.jvPartnership': { en: 'JV partnerships with global brands - our skilled R&D team and hardware/software experts can develop any feature you need', he: 'שותפות JV עם מותגים גלובליים - צוות R&D המיומן שלנו ומומחי חומרה/תוכנה יכולים לפתח כל תכונה שאתה צריך', ar: 'شراكات المشاريع المشتركة مع العلامات التجارية العالمية - فريق البحث والتطوير الماهر لدينا وخبراء الأجهزة / البرامج يمكنهم تطوير أي ميزة تحتاجها', ru: 'JV партнёрства с глобальными брендами - наша опытная R&D команда и эксперты по оборудованию/ПО могут разработать любую функцию', fr: 'Partenariats JV avec des marques mondiales - notre équipe R&D qualifiée et nos experts matériel/logiciel peuvent développer toute fonctionnalité dont vous avez besoin', es: 'Asociaciones JV con marcas globales - nuestro equipo de I+D calificado y expertos en hardware/software pueden desarrollar cualquier función que necesites' },
  'franchise.customFeatures': { en: 'Custom feature development tailored to your exact needs', he: 'פיתוח תכונות בהתאמה אישית לצרכים המדויקים שלך', ar: 'تطوير الميزات المخصصة المصممة وفقًا لاحتياجاتك الدقيقة', ru: 'Разработка кастомных функций под ваши точные нужды', fr: 'Développement de fonctionnalités personnalisées adaptées à vos besoins exacts', es: 'Desarrollo de funciones personalizadas adaptadas a tus necesidades exactas' },
  'franchise.topExperts': { en: 'Top-tier hardware and software specialists', he: 'מומחי חומרה ותוכנה מהשורה הראשונה', ar: 'متخصصون من الدرجة الأولى في الأجهزة والبرامج', ru: 'Специалисты высшего уровня по оборудованию и ПО', fr: 'Spécialistes de haut niveau en matériel et logiciel', es: 'Especialistas de primer nivel en hardware y software' },
  'franchise.tellUsWhatWhenHow': { en: 'Tell us what, when, and how - we\'ll find the perfect solution', he: 'ספר לנו מה, מתי ואיך - נמצא את הפתרון המושלם', ar: 'أخبرنا ماذا ومتى وكيف - سنجد الحل المثالي', ru: 'Скажите нам что, когда и как - мы найдём идеальное решение', fr: 'Dites-nous quoi, quand et comment - nous trouverons la solution parfaite', es: 'Dinos qué, cuándo y cómo - encontraremos la solución perfecta' },
  'franchise.systemsCertified': { en: 'All systems include: EPA Registered, CE Conformity, ATS 5200.101:2005 Strength of Assembly', he: 'כל המערכות כוללות: EPA Registered, CE Conformity, ATS 5200.101:2005 Strength of Assembly', ar: 'تتضمن جميع الأنظمة: مسجل لدى EPA، توافق CE، ATS 5200.101:2005 قوة التجميع', ru: 'Все системы включают: EPA Registered, CE Conformity, ATS 5200.101:2005 Strength of Assembly', fr: 'Tous les systèmes incluent: EPA Registered, CE Conformity, ATS 5200.101:2005 Strength of Assembly', es: 'Todos los sistemas incluyen: EPA Registered, CE Conformity, ATS 5200.101:2005 Strength of Assembly' },
  'franchise.ensureAccuracy': { en: '⚠️ Ensure all information you provide is accurate and truthful', he: '⚠️ וודא שכל המידע שאתה מספק נכון ומדויק', ar: '⚠️ تأكد من أن جميع المعلومات التي تقدمها دقيقة وصادقة', ru: '⚠️ Убедитесь, что вся предоставляемая информация точна и правдива', fr: '⚠️ Assurez-vous que toutes les informations que vous fournissez sont exactes et véridiques', es: '⚠️ Asegúrate de que toda la información que proporciones sea precisa y veraz' },
  'franchise.joinGlobalNetwork': { en: 'Join the world\'s leading network and become a successful business owner', he: 'הצטרף לרשת העולמית המובילה והפוך לבעלים של עסק מצליח', ar: 'انضم إلى الشبكة الرائدة في العالم وأصبح مالك عمل ناجح', ru: 'Присоединяйтесь к ведущей мировой сети и станьте успешным владельцем бизнеса', fr: 'Rejoignez le réseau mondial leader et devenez un propriétaire d\'entreprise prospère', es: 'Únete a la red líder mundial y conviértete en un propietario de negocio exitoso' },
