  'googleConsent.ready.concurrent': { en: '🌍 Ready for 1000+ Concurrent Users', he: '🌍 מוכן ל-1000+ משתמשים במקביל', ar: '🌍 جاهز لأكثر من 1000 مستخدم متزامن', ru: '🌍 Готово для 1000+ одновременных пользователей', fr: '🌍 Prêt pour 1000+ utilisateurs simultanés', es: '🌍 Listo para 1000+ usuarios concurrentes' },
  'googleConsent.ready.checked': { en: '✅ Everything Checked & Ready', he: '✅ הכל מסומן ומוכן', ar: '✅ كل شيء محدد وجاهز', ru: '✅ Всё отмечено и готово', fr: '✅ Tout est coché et prêt', es: '✅ Todo marcado y listo' },
  'googleConsent.security.encrypted': { en: 'Encrypted & Secured with AES-256', he: 'מוצפן ומאובטח עם AES-256', ar: 'مشفر ومؤمن باستخدام AES-256', ru: 'Зашифровано и защищено AES-256', fr: 'Crypté et sécurisé avec AES-256', es: 'Encriptado y asegurado con AES-256' },
  'googleConsent.footer.changePermissions': { en: 'You can change permissions anytime via', he: 'ניתן לשנות הרשאות בכל עת דרך', ar: 'يمكنك تغيير الأذونات في أي وقت عبر', ru: 'Вы можете изменить разрешения в любое время через', fr: 'Vous pouvez modifier les autorisations à tout moment via', es: 'Puedes cambiar permisos en cualquier momento a través de' },
