  'googleConsent.footer.ofPetWash': { en: 'of Pet Wash™ Ltd', he: 'של Pet Wash™ Ltd', ar: 'من Pet Wash™ Ltd', ru: 'Pet Wash™ Ltd', fr: 'de Pet Wash™ Ltd', es: 'de Pet Wash™ Ltd' },
  // Google Consent Additional Keys
  'googleConsent.success.allServices': { en: 'All 13 Google Cloud Services Approved & Active', he: 'כל 13 שירותי Google Cloud מאושרים ופעילים', ar: 'جميع خدمات Google Cloud الـ 13 معتمدة ونشطة', ru: 'Все 13 сервисов Google Cloud одобрены и активны', fr: 'Les 13 services Google Cloud approuvés et actifs', es: 'Los 13 servicios de Google Cloud aprobados y activos' },
  'googleConsent.success.encryption': { en: 'All data encrypted with AES-256. You can revoke access anytime via your Google Account.', he: 'כל הנתונים מוצפנים עם AES-256. ניתן לבטל גישה בכל עת דרך חשבון Google שלך.', ar: 'جميع البيانات مشفرة باستخدام AES-256. يمكنك إلغاء الوصول في أي وقت عبر حساب Google الخاص بك.', ru: 'Все данные зашифрованы с помощью AES-256. Вы можете отозвать доступ в любое время через свой аккаунт Google.', fr: 'Toutes les données cryptées avec AES-256. Vous pouvez révoquer l\'accès à tout moment via votre compte Google.', es: 'Todos los datos encriptados con AES-256. Puedes revocar el acceso en cualquier momento a través de tu cuenta de Google.' },
  'googleConsent.header.subtitle': { en: 'Authorize access to 13 Google Cloud Services for seamless global operations', he: 'יש לאשר גישה ל-13 שירותי Google Cloud לצורך תפעול גלובלי מושלם', ar: 'تفويض الوصول إلى 13 خدمة Google Cloud لعمليات عالمية سلسة', ru: 'Авторизуйте доступ к 13 сервисам Google Cloud для бесперебойных глобальных операций', fr: 'Autoriser l\'accès à 13 services Google Cloud pour des opérations mondiales transparentes', es: 'Autorizar acceso a 13 servicios de Google Cloud para operaciones globales sin problemas' },
  'googleConsent.ready.configured': { en: 'All Google Cloud Services configured for enterprise-scale global operations. Full support for 6 languages, multi-country franchises, and automated AI.', he: 'כל שירותי Google Cloud מוגדרים לתפעול גלובלי בקנה מידה עסקי. תמיכה מלאה ב-6 שפות, פרנציזים רב-מדינתיים ו-AI אוטומטי.', ar: 'جميع خدمات Google Cloud مهيأة للعمليات العالمية على مستوى المؤسسات. دعم كامل لـ 6 لغات، امتيازات متعددة البلدان، والذكاء الاصطناعي الآلي.', ru: 'Все сервисы Google Cloud настроены для корпоративных глобальных операций. Полная поддержка 6 языков, международных франшиз и автоматизированного ИИ.', fr: 'Tous les services Google Cloud configurés pour des opérations mondiales à l\'échelle de l\'entreprise. Prise en charge complète de 6 langues, franchises multinationales et IA automatisée.', es: 'Todos los servicios de Google Cloud configurados para operaciones globales a escala empresarial. Soporte completo para 6 idiomas, franquicias multinacionales e IA automatizada.' },
