  'k9000.badge': { en: 'Self-Service Pet Wash Stations', he: 'תחנות רחיצה בשירות עצמי', ar: 'محطات غسيل الخدمة الذاتية', ru: 'Станции самообслуживания', fr: 'Stations de lavage en libre-service', es: 'Estaciones de lavado autoservicio' },
