  'k9000.subtitle': { en: 'Professional self-service pet washing stations with organic products. State-of-the-art technology, 24/7 availability.', he: 'תחנות רחיצת חיות מחמד מקצועיות בשירות עצמי עם מוצרים אורגניים. טכנולוגיה מתקדמת, זמינות 24/7.', ar: 'محطات غسيل ذاتية الخدمة احترافية مع منتجات عضوية. تقنية متطورة، متاحة 24/7.', ru: 'Профессиональные станции самообслуживания с органической продукцией. Передовые технологии, доступность 24/7.', fr: 'Stations de lavage professionnelles en libre-service avec produits bio. Technologie de pointe, disponible 24/7.', es: 'Estaciones de lavado profesionales autoservicio con productos orgánicos. Tecnología avanzada, disponible 24/7.' },
  'k9000.bookWash': { en: 'Book a Wash Now', he: 'הזמן רחיצה עכשיו', ar: 'احجز غسيلاً الآن', ru: 'Забронировать мойку', fr: 'Réserver un lavage', es: 'Reservar lavado ahora' },
