  'k9000.findStationDesc': { en: 'Locate K9000 stations near you', he: 'אתר תחנות K9000 בקרבתך', ar: 'حدد موقع محطات K9000 بالقرب منك', ru: 'Найти станции K9000 рядом с вами', fr: 'Trouver des stations K9000 près de chez vous', es: 'Encontrar estaciones K9000 cerca de ti' },
  'k9000.myWashes': { en: 'My Washes', he: 'הרחיצות שלי', ar: 'عمليات الغسيل الخاصة بي', ru: 'Мои мойки', fr: 'Mes lavages', es: 'Mis lavados' },
  'k9000.myWashesDesc': { en: 'View your wash history', he: 'צפה בהיסטוריית הרחיצות שלך', ar: 'عرض سجل الغسيل الخاص بك', ru: 'Просмотр истории моек', fr: 'Voir votre historique de lavages', es: 'Ver tu historial de lavados' },
  'k9000.packages': { en: 'Wash Packages', he: 'חבילות רחיצה', ar: 'باقات الغسيل', ru: 'Пакеты мойки', fr: 'Forfaits de lavage', es: 'Paquetes de lavado' },
  'k9000.packagesDesc': { en: 'Save with package deals', he: 'חסוך עם עסקאות חבילות', ar: 'وفر مع عروض الباقات', ru: 'Экономьте с пакетами', fr: 'Économisez avec les forfaits', es: 'Ahorra con paquetes' },
  'k9000.products': { en: 'Our Products', he: 'המוצרים שלנו', ar: 'منتجاتنا', ru: 'Наши продукты', fr: 'Nos produits', es: 'Nuestros productos' },
  'k9000.productsDesc': { en: 'Premium organic pet care products', he: 'מוצרי טיפוח אורגניים פרמיום', ar: 'منتجات رعاية عضوية ممتازة', ru: 'Органические товары премиум класса', fr: 'Produits bio premium pour animaux', es: 'Productos orgánicos premium' },
  'k9000.helpDesc': { en: 'Get assistance with K9000 stations', he: 'קבל עזרה עם תחנות K9000', ar: 'احصل على المساعدة مع محطات K9000', ru: 'Получить помощь со станциями K9000', fr: 'Obtenir de l\'aide avec les stations K9000', es: 'Obtener ayuda con las estaciones K9000' },
  'k9000.organic': { en: '100% Organic', he: '100% אורגני', ar: '100% عضوي', ru: '100% органика', fr: '100% Bio', es: '100% Orgánico' },
  'k9000.organicDesc': { en: 'Natural products only', he: 'רק מוצרים טבעיים', ar: 'منتجات طبيعية فقط', ru: 'Только натуральные продукты', fr: 'Produits naturels uniquement', es: 'Solo productos naturales' },
  'k9000.available247': { en: 'Available 24/7', he: 'זמין 24/7', ar: 'متاح 24/7', ru: 'Доступно 24/7', fr: 'Disponible 24/7', es: 'Disponible 24/7' },
