  'k9000.ecoFriendlyDesc': { en: 'Water-saving technology', he: 'טכנולוגיית חיסכון במים', ar: 'تقنية توفير المياه', ru: 'Водосберегающие технологии', fr: 'Technologie économe en eau', es: 'Tecnología de ahorro de agua' },
