  'k9000.safetyDesc': { en: 'Learn how to use K9000 stations safely', he: 'למד כיצד להשתמש בתחנות K9000 בבטחה', ar: 'تعلم كيفية استخدام محطات K9000 بأمان', ru: 'Узнайте как безопасно использовать станции K9000', fr: 'Apprenez à utiliser les stations K9000 en toute sécurité', es: 'Aprende a usar las estaciones K9000 de forma segura' },
