  'pettrek.customTrips': { en: 'Custom Trips', he: 'נסיעות מותאמות', ar: 'رحلات مخصصة', ru: 'Индивидуальные поездки', fr: 'Trajets personnalisés', es: 'Viajes personalizados' },
  'pettrek.customTripsDesc': { en: 'Any destination, any time - we\'ve got you covered', he: 'כל יעד, כל זמן - אנחנו מכסים אותך', ar: 'أي وجهة، أي وقت - نحن نغطيك', ru: 'Любое направление, любое время - мы вас обеспечим', fr: 'N\'importe quelle destination, n\'importe quand', es: 'Cualquier destino, cualquier hora - te cubrimos' },
  'pettrek.groomingAppointments': { en: 'Grooming Appointments', he: 'טיפוח וטיפול', ar: 'مواعيد العناية', ru: 'Записи на груминг', fr: 'Rendez-vous toilettage', es: 'Citas de peluquería' },
  'pettrek.groomingAppointmentsDesc': { en: 'Drop-off and pickup from your favorite groomer', he: 'הורדה ואיסוף ממטפח הפרווה האהוב עליך', ar: 'التوصيل والاستلام من مصفف الشعر المفضل لديك', ru: 'Доставка и забор от грумера', fr: 'Dépose et récupération chez votre toiletteur', es: 'Entrega y recogida de tu peluquero favorito' },
  'pettrek.step1Title': { en: 'Choose Your Route', he: 'בחר את המסלול', ar: 'اختر طريقك', ru: 'Выберите маршрут', fr: 'Choisissez votre trajet', es: 'Elige tu ruta' },
  'pettrek.step1Desc': { en: 'Enter pickup and drop-off locations, select service type and time', he: 'הזן מיקומי איסוף והורדה, בחר סוג שירות וזמן', ar: 'أدخل مواقع الاستلام والتوصيل، اختر نوع الخدمة والوقت', ru: 'Введите точки посадки и высадки, выберите тип услуги и время', fr: 'Entrez les lieux de prise en charge et de dépose, sélectionnez le type de service et l\'heure', es: 'Ingresa las ubicaciones de recogida y entrega, selecciona el tipo de servicio y la hora' },
  'pettrek.step2Title': { en: 'Match with Driver', he: 'התאמת נהג', ar: 'تطابق مع سائق', ru: 'Подбор водителя', fr: 'Mise en relation avec un chauffeur', es: 'Empareja con un conductor' },
  'pettrek.step2Desc': { en: 'Get matched with verified, pet-trained drivers in your area', he: 'קבל התאמה לנהגים מאומתים ומאומנים לחיות מחמד באזורך', ar: 'احصل على مطابقة مع سائقين معتمدين ومدربين على التعامل مع الحيوانات في منطقتك', ru: 'Получите подходящего проверенного водителя, обученного работе с питомцами, в вашем районе', fr: 'Soyez mis en relation avec des chauffeurs vérifiés et formés aux animaux dans votre région', es: 'Encuentra conductores verificados y entrenados en mascotas en tu zona' },
  'pettrek.step3Title': { en: 'Track & Relax', he: 'עקוב ונוח', ar: 'تتبع واسترخ', ru: 'Отслеживайте и расслабьтесь', fr: 'Suivez et détendez-vous', es: 'Rastrea y relájate' },
  'pettrek.step3Desc': { en: 'Follow your pet\'s journey in real-time with GPS tracking', he: 'עקוב אחר מסע חיית המחמד שלך בזמן אמת עם מעקב GPS', ar: 'تابع رحلة حيوانك الأليف في الوقت الفعلي مع تتبع GPS', ru: 'Следите за поездкой вашего питомца в реальном времени с GPS-отслеживанием', fr: 'Suivez le trajet de votre animal en temps réel avec le suivi GPS', es: 'Sigue el viaje de tu mascota en tiempo real con seguimiento GPS' },
  'pettrek.featuredDrivers': { en: 'Featured Drivers', he: 'נהגים מובילים', ar: 'السائقون المميزون', ru: 'Лучшие водители', fr: 'Chauffeurs en vedette', es: 'Conductores destacados' },
  'pettrek.featuredDriversSubtitle': { en: 'Meet our top-rated pet transport professionals', he: 'הכירו את מקצועני ההסעות המובילים שלנו', ar: 'تعرف على أفضل متخصصي نقل الحيوانات الأليفة لدينا', ru: 'Познакомьтесь с нашими лучшими профессионалами по перевозке питомцев', fr: 'Rencontrez nos meilleurs professionnels du transport', es: 'Conoce a nuestros mejores profesionales del transporte' },
  'pettrek.safety': { en: 'Your Pet\'s Safety First', he: 'בטיחות חיית המחמד שלך קודמת', ar: 'سلامة حيوانك الأليف أولاً', ru: 'Безопасность вашего питомца прежде всего', fr: 'La sécurité de votre animal d\'abord', es: 'La seguridad de tu mascota primero' },
