  'pettrek.gpsTrackingDesc': { en: 'Real-time location updates and route monitoring throughout the journey', he: 'עדכוני מיקום בזמן אמת ומעקב מסלול לאורך כל הנסיעה', ar: 'تحديثات الموقع في الوقت الفعلي ومراقبة المسار طوال الرحلة', ru: 'Обновления местоположения в реальном времени и мониторинг маршрута на протяжении всей поездки', fr: 'Mises à jour de localisation en temps réel et surveillance du trajet tout au long du voyage', es: 'Actualizaciones de ubicación en tiempo real y monitoreo de ruta durante todo el viaje' },
  'pettrek.verifiedDrivers': { en: 'Verified Drivers', he: 'נהגים מאומתים', ar: 'سائقون معتمدون', ru: 'Проверенные водители', fr: 'Chauffeurs vérifiés', es: 'Conductores verificados' },
  'pettrek.verifiedDriversDesc': { en: 'All drivers undergo comprehensive background checks and pet safety training', he: 'כל הנהגים עוברים בדיקות רקע מקיפות והכשרה לבטיחות חיות מחמד', ar: 'جميع السائقين يخضعون لفحوصات خلفية شاملة وتدريب على سلامة الحيوانات الأليفة', ru: 'Все водители проходят комплексную проверку биографии и обучение безопасности питомцев', fr: 'Tous les chauffeurs passent des vérifications approfondies et une formation à la sécurité des animaux', es: 'Todos los conductores pasan verificaciones exhaustivas y capacitación en seguridad de mascotas' },
  'pettrek.fullyInsured': { en: 'Fully Insured', he: 'ביטוח מלא', ar: 'مؤمن بالكامل', ru: 'Полная страховка', fr: 'Entièrement assuré', es: 'Totalmente asegurado' },
  'pettrek.pricingSubtitle': { en: 'Simple, fair rates with no hidden fees', he: 'תעריפים פשוטים והוגנים ללא עמלות נסתרות', ar: 'أسعار بسيطة وعادلة بدون رسوم مخفية', ru: 'Простые и честные тарифы без скрытых комиссий', fr: 'Tarifs simples et équitables sans frais cachés', es: 'Tarifas simples y justas sin cargos ocultos' },
