  'vito.benefit3': { en: 'Birthday rewards for you and your pet', he: 'מתנות יום הולדת לך ולחיית המחמד שלך', ar: 'مكافآت أعياد الميلاد لك ولحيوانك الأليف', ru: 'Подарки на день рождения для вас и вашего питомца', fr: 'Récompenses d\'anniversaire pour vous et votre animal', es: 'Recompensas de cumpleaños para ti y tu mascota' },
