  'vito.benefit6': { en: 'Early access to new services & products', he: 'גישה מוקדמת לשירותים ומוצרים חדשים', ar: 'وصول مبكر إلى الخدمات والمنتجات الجديدة', ru: 'Ранний доступ к новым услугам и продуктам', fr: 'Accès anticipé aux nouveaux services et produits', es: 'Acceso anticipado a nuevos servicios y productos' },
